    const val SHAPE_ID_BASE = 1

    /**
     * Единый helper: строит [Path] из SVG d-path, приведённый из viewBox 216x216
     * в заданный размер (fit-center, без pivot-бага). Трансформация вшита в путь,
     * поэтому Path рисуется напрямую drawPath/clipPath без ручного scale/translate.
     */
    fun shapePath(d: String, size: Size): Path? =
        runCatching {
            PathParser().parsePathString(normalizeSvgPath(d)).toPath().apply {
                fillType = PathFillType.EvenOdd
                val s = min(size.width, size.height) / 216f
                val tx = (size.width - 216f * s) / 2f
                val ty = (size.height - 216f * s) / 2f
                transform(Matrix().apply { scale(s, s); translate(tx / s, ty / s) })
            }
        }.getOrNull()

    /**
     * Нормализует SVG d-path перед парсингом Compose [PathParser]. Сложные формы
     * (сердце/зверёк/цветок) содержат валидные в SVG, но несовместимые с
     * parsePathString токены: ведущие точки (`.N`), знак с точкой (`-.N`) и
     * склеенные числа через неявный разделитель (`N.N.N`). PathParser трактует
     * `.`+цифры как одно число, на второй точке делает toFloat() ->
     * NumberFormatException, и форма возвращает null. Сканер посимвольно
     * разбирает на числа (знак + мантисса с ОДНОЙ точкой), вставляет пробел-
     * разделитель между склеенными числами и нормализует ведущую точку в `0.N`.
     * Работает и для «чистых» путей (форм 4-9, круг) без изменений.
     */
    fun normalizeSvgPath(d: String): String {
        if (d.isEmpty()) return d
        val sb = StringBuilder(d.length + 16)
        var i = 0
        val n = d.length
        while (i < n) {
            val c = d[i]
            if (c.isLetter()) {
                sb.append(c)
                i++
                continue
            }
            // Признак начала числа: цифра, '.' или знак перед цифрой/точкой.
            val startsNumber = c.isDigit() || c == '.' || (
                (c == '-' || c == '+') && i + 1 < n && (d[i + 1].isDigit() || d[i + 1] == '.')
            )
            if (!startsNumber) {
                sb.append(c)
                i++
                continue
            }
            // Знак числа (если есть).
            var sign = ""
            if (c == '-' || c == '+') {
                sign = c.toString()
                i++
            }
            // Мантисса: цифры и максимум одна точка.
            val mant = StringBuilder()
            var sawDot = false
            while (i < n) {
                val ch = d[i]
                when {
                    ch.isDigit() -> {
                        mant.append(ch); i++
                    }
                    ch == '.' && !sawDot -> {
                        sawDot = true; mant.append(ch); i++
                    }
                    else -> break
                }
            }
            var mantStr = mant.toString()
            if (mantStr.startsWith(".")) mantStr = "0" + mantStr  // `.N` -> `0.N`
            sb.append(sign).append(mantStr)
            // Если следующая точка/цифра приклеилась бы к числу (N.N.N), разделяем пробелом.
            val next = if (i < n) d[i] else '\u0000'
            if (mantStr.isNotEmpty() && mantStr.last().isDigit() && (next == '.' || next.isDigit())) {
                sb.append(' ')
            }
        }
        return sb.toString()
    }

    /** [shapePath] по id формы (SHAPE_ID_BASE); фолбэк на первую форму. */
    fun shapePathByShapeId(shapeId: Int, size: Size): Path? {
        val d = PATHS.getOrNull(shapeId - SHAPE_ID_BASE) ?: PATHS.firstOrNull() ?: return null
        return shapePath(d, size)
    }
